  "headline": "Ertapenem is not on FDA's shortage list as of 2026-10-21; Corvale East has 30 days on hand and Corvale General has 21.7 days on hand",
  "headline_cites": ["D3", "D1", "D2"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows ertapenem is not listed as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 448 vials of ertapenem 1 g injection with a daily use of 14.9 vials, providing 30 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 722 vials of ertapenem 1 g injection with a daily use of 33.2 vials, providing 21.7 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The top-ranked purchasing option is to buy from Apotex Corp., which is not on FDA's shortage list today, though its label names no plant we could place.",
      "cites": ["D4"]
    },
    {
      "text": "Secondary options include BluePoint Laboratories and Dr.Reddys Laboratories Inc., both also not on FDA's shortage list today and with labels naming no plant we could place.",
      "cites": ["D5", "D6"]
    },
    {
      "text": "A registered manufacturing plant for ertapenem is ACS Dobfar SpA (FEI 3006028606) in Italy, which received a VAI classification on its most recent inspection ending 2024-12-13.",
      "cites": ["E14", "E12"]
    },
    {
      "text": "That plant has a history including an OAI classification in 2016 and a Warning Letter in 2017, but subsequent inspections in 2017, 2018, 2022, and 2024 were classified VAI.",
      "cites": ["E8", "E13", "E9", "E10", "E11", "E12"]
    }
  ]
}
